use xiom.io;
fn has_duplicate(items: Vec[Str]) -> Bool {
  let seen: Set[Str] = Set[Str].new();
  for item in items {
    if seen.contains(item) { return true; }
    seen.insert(item);
  }
  return false;
}

fn main() -> Int {
  let nums: Vec[Str] = Vec[Str].new();
  nums.push("a");
  nums.push("b");
  nums.push("c");
  nums.push("a");

  io.println(has_duplicate(nums).to_str());
  return 0;
}
